class PriceFormatter {
  constructor(currency) {
    this.currency = currency;
  }

  format(amount) {
    return `${amount.toFixed(2)} ${this.currency}`;
  }
}

const egp = new PriceFormatter("EGP");
// call it as a method inside an arrow function...
console.log([120, 80].map((amount) => egp.format(amount)));
// ...or pass a bound copy whose this is fixed
console.log([120, 80].map(egp.format.bind(egp)));
// both print [ '120.00 EGP', '80.00 EGP' ]

