"use strict";

function describe() {
  return this === undefined ? "no this" : this.name;
}

const cart = { name: "cart", describe };
const wishlist = { name: "wishlist", describe: cart.describe };

console.log(cart.describe()); // cart
console.log(wishlist.describe()); // wishlist: same function, new receiver
const detached = cart.describe;
console.log(detached()); // no this: nothing before the dot
console.log(describe.call({ name: "order" })); // order
const bound = describe.bind(cart);
console.log(bound.call(wishlist)); // cart: bind beats call
console.log(bound.bind(wishlist)()); // cart: you can't re-bind
